mu=D[num].mean();sd=D[num].std();N=(D[num]-mu)/sd
Z=pd.DataFrame(index=D.index)
for c in num:Z[c]=N[c];Z[c+'^2']=N[c]**2
Z=pd.concat([Z,pd.get_dummies(D[cat],drop_first=True,dtype=float)],axis=1)
s=StandardScaler().fit(Z);m=Ridge(alpha=.01).fit(s.transform(Z),y)
def effective(mm,ss): return mm.coef_/ss.scale_, mm.intercept_-np.sum(mm.coef_*ss.mean_/ss.scale_)
def optima(mm,ss):
 coef,inter=effective(mm,ss); x=[]
 for c in num:
  b1=coef[Z.columns.get_loc(c)];b2=coef[Z.columns.get_loc(c+'^2')];zz=-b1/(2*b2)
  val=mu[c]+sd[c]*zz
  if b2<0: val=np.clip(val,D[c].min(),D[c].max())
  else:
   grid=np.array([D[c].min(),D[c].max()]);zg=(grid-mu[c])/sd[c];val=grid[np.argmax(b1*zg+b2*zg**2)]
  x.append(val)
 return np.array(x),coef,inter
x,coef,inter=optima(m,s)
def makez(x,heat,route):
 n=(x-mu.to_numpy())/sd.to_numpy();v=[]
 for a in n:v.extend([a,a*a])
 for c in Z.columns[32:]:
  if c.startswith('heat_treatment_'):v.append(float(heat==c[len('heat_treatment_'):]))
  else:v.append(float(route==c[len('route_'):]))
 return np.array(v)
best=(-1,None,None)
for heat in D.heat_treatment.unique():
 for route in D.route.unique():
  p=m.predict(s.transform(makez(x,heat,route).reshape(1,-1)))[0]
