rng=np.random.default_rng(73);opts=[];preds=[]
for k in range(500):
 ix=rng.integers(0,len(D),len(D));ss=StandardScaler().fit(Z.iloc[ix]);mm=Ridge(alpha=.01).fit(ss.transform(Z.iloc[ix]),y[ix]); xx,_,_=optima(mm,ss);opts.append(xx)
 # evaluate bootstrap model at its optimum and full-model prediction there
 preds.append([mm.predict(ss.transform(makez(xx,'solution_aged','wrought').reshape(1,-1)))[0],m.predict(s.transform(makez(xx,'solution_aged','wrought').reshape(1,-1)))[0]])
