import pandas as pd,numpy as np
from sklearn.model_selection import RepeatedKFold
from sklearn.preprocessing import StandardScaler
from sklearn.linear_model import Ridge
D=pd.read_csv('/work/alloy_pair_max_train.csv');y=D.pop('target').to_numpy();cat=['heat_treatment','route'];cv=list(RepeatedKFold(n_splits=5,n_repeats=5,random_state=73).split(D))
def design(cols,degree=2):
 N=(D[cols]-D[cols].mean())/D[cols].std(); z=[]
 for p in range(1,degree+1):z.append(N**p)
 return np.c_[*z,pd.get_dummies(D[cat],drop_first=True,dtype=float)]
def score(X,a=.01):
 ae=[];se=[]
 for tr,te in cv:
  s=StandardScaler().fit(X[tr]);m=Ridge(alpha=a).fit(s.transform(X[tr]),y[tr]);e=y[te]-m.predict(s.transform(X[te]));ae.extend(abs(e));se.extend(e*e)
 return np.mean(ae),np.sqrt(np.mean(se))
num=[c for c in D if c not in cat]
for cols in [num,[c for c in num if c!='Fe']]:
 for deg,a in [(1,.01),(2,.01),(3,.1)]:print('Fe',('Fe' in cols),'deg',deg,score(design(cols,deg),a))
