import pandas as pd,numpy as np
from scipy.optimize import differential_evolution, minimize
D=pd.read_csv('/work/alloy_pair_max_train.csv');y=D.pop('target').to_numpy();cat=['heat_treatment','route'];outnum=['C','Mn','Si','Cr','Ni','Mo','V','Nb','Co','Al','Ti','Cu','solutionizing_temp','aging_temp','aging_time','cooling_rate']; allnum=outnum[:12]+['Fe']+outnum[12:]
mu=D[allnum].mean();sd=D[allnum].std();N=(D[allnum]-mu)/sd
cats=pd.get_dummies(D[cat],drop_first=True,dtype=float)
pairs=[('Mn','cooling_rate'),('Cr','Co'),('aging_temp','aging_time'),('Mo','Co'),('C','Cr')]
# Fe linear is omitted because it is exactly collinear with the 12 alloying-element linear terms.
cols=[]
for c in allnum:
 if c!='Fe':cols.append(c)
for c in allnum:cols.append(c+'^2')
cols += list(cats.columns)+[a+'*'+b for a,b in pairs]
def features_frame(df):
 nn=(df[allnum]-mu)/sd; z=pd.DataFrame(index=df.index)
 for c in allnum:
  if c!='Fe':z[c]=nn[c]
 for c in allnum:z[c+'^2']=nn[c]**2
 for c in cats.columns:
  if c.startswith('heat_treatment_'):z[c]=(df.heat_treatment==c[len('heat_treatment_'):]).astype(float)
  else:z[c]=(df.route==c[len('route_'):]).astype(float)
 for a,b in pairs:z[a+'*'+b]=nn[a]*nn[b]
 return z[cols].to_numpy()
X=np.c_[np.ones(len(D)),features_frame(D)];coef=np.linalg.lstsq(X,y,rcond=None)[0]
resid=y-X@coef
print('train MAE/RMSE',np.mean(abs(resid)),np.sqrt(np.mean(resid**2)))
bounds=[(D[c].min(),D[c].max()) for c in outnum]
def predict(x,heat='solution_aged',route='wrought'):
 row={c:v for c,v in zip(outnum,x)};row['Fe']=100-sum(x[:12]);row['heat_treatment']=heat;row['route']=route
 q=pd.DataFrame([row]);return np.r_[1,features_frame(q)[0]]@coef
# Keep all explicit features in observed range; Fe naturally remains in range here.
def objective(x):
 s=sum(x[:12]); fe=100-s
 if s>100 or fe<D.Fe.min() or fe>D.Fe.max():return 1e6+(s-100)**2
 return -predict(x)
res=differential_evolution(objective,bounds,seed=20260907,popsize=40,maxiter=3000,tol=1e-12,polish=True,workers=1)
# Refine with SLSQP
cons=[{'type':'ineq','fun':lambda x:100-sum(x[:12])},{'type':'ineq','fun':lambda x:100-sum(x[:12])-D.Fe.min()},{'type':'ineq','fun':lambda x:D.Fe.max()-(100-sum(x[:12]))}]
rr=minimize(lambda x:-predict(x),res.x,method='SLSQP',bounds=bounds,constraints=cons,options={'ftol':1e-12,'maxiter':5000})
x=rr.x
print('success',res.success,rr.success,rr.message)
print('pred',predict(x),'sum alloy',sum(x[:12]),'Fe',100-sum(x[:12]))
for c,v in zip(outnum,x):print(c,f'{v:.10f}', 'bounds',bounds[outnum.index(c)])
print('\ncategorical predictions')
for h in D.heat_treatment.unique():
 for r in D.route.unique():print(h,r,predict(x,h,r))
# Validate rounded 4-decimal recipe
xr=np.round(x,4);print('\nrounded pred',predict(xr),'sum',sum(xr[:12]),'Fe',100-sum(xr[:12]))
for c,v in zip(outnum,xr):print(f'{c}={v:.4f}')
